SELECT * FROM candidate_score
WHERE jd_id = #{jdId}
ORDER BY total_score DESC

SELECT * FROM candidate_score
WHERE candidate_id = #{candidateId}
ORDER BY created_at DESC

SELECT * FROM candidate_score
WHERE candidate_id = #{candidateId} AND jd_id = #{jdId}
LIMIT 1

SELECT * FROM candidate_score
WHERE jd_id = #{jdId} AND total_score >= #{threshold}
ORDER BY total_score DESC
